    font-family: arial;
    font-size: 20px;
    text-align: center;
    color: black;
    background-color: white;
}

.cloze {
 font-weight: bold;
 color: blue;
}
.nightMode .cloze {
 color: lightblue;
}

td.pm, td.pc { display: none; }
td.pm.show, td.pc.show { display: table-cell; }
.pm-toggle { font-size: 0.8em; color: #888; text-decoration: underline; cursor: pointer; display: inline-block; margin: 0 8px 6px; }

.audio-row { text-align: center; margin: 10px 0 1.2em; }
.example { margin-top: 4px; }

